"""Backend-only guard against restoring routes generated by older algorithms.

The route algorithm is *never* edited, cached, or interpreted here. The fingerprint
only helps us identify results saved under a previous algorithm revision.
"""
from __future__ import annotations
import hashlib
from pathlib import Path
from django.conf import settings

# Include the source files that determine route selection and Uber estimates.
_ALGORITHM_MODULES = (
    'main_alg.py', 'helpers.py', 'least_cost_path.py', 'process.py',
    'aggregator.py', 'flight_scraper/google_flights_scraper.py',
    'Amtrack_Scraper/Amtrak_Data.py', 'greyhound/greyhound_search.py',
)

def algorithm_revision():
    root = Path(settings.BASE_DIR) / 'Algorithm'
    digest = hashlib.sha256()
    for name in _ALGORITHM_MODULES:
        filename = root / name
        digest.update(name.encode('utf-8'))
        if filename.is_file():
            digest.update(filename.read_bytes())
        else:
            digest.update(b'<missing>')
    return digest.hexdigest()


def discard_outdated_results(request):
    """Remove stale output while preserving search form input for re-use."""
    saved = ('planner_saved_display', 'planner_saved_json', 'search_history')
    if not any(key in request.session for key in saved):
        return False
    if request.session.get('planner_algorithm_revision') == algorithm_revision():
        return False
    for key in saved:
        request.session.pop(key, None)
    request.session.pop('planner_algorithm_revision', None)
    return True
